export interface Receipt { id: number; tenant: string; key: string; cents: number }
export class Ledger {
  readonly entries: Receipt[] = [];
  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    if (typeof tenant !== 'string' || !tenant || typeof key !== 'string' || !key ||
        !Number.isInteger(cents) || cents <= 0) throw new Error('invalid payment');
    // Lookup and commit are synchronous, so concurrent callers cannot both debit.
    const existing = this.entries.find(entry => entry.tenant === tenant && entry.key === key);
    if (existing) {
      if (existing.cents !== cents) throw new Error('key conflict');
      return existing;
    }
    const receipt = { id: this.entries.length + 1, tenant, key, cents };
    this.entries.push(receipt);
    return receipt;
  }
}
